ui-refresh.css:
/* Release 129: three local card refinements; preserve typography and hit targets. */
body .quick-asset .quick-asset-name-row{gap:4px}
body .quick-asset-name-row small{flex:0 1 auto;max-width:38%;min-width:0;margin:0;font-size:10px;line-height:1.3;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* Reclaim real layout padding, not a translated checkbox or overlapping hit area. */
body .asset-card .asset-details{padding-inline:0}
body .json-reference-list,body.dark .json-reference-list{grid-template-columns:repeat(2,minmax(0,1fr))}
@media(max-width:299px){body .json-reference-list,body.dark .json-reference-list{grid-template-columns:minmax(0,1fr)}}
body .json-reference-row{min-height:72px;grid-template-columns:44px 62px minmax(0,1fr)}
body .json-reference-thumb{width:56px;height:56px}
@media(max-width:700px){
 body .json-reference-row{min-height:60px;grid-template-columns:44px 32px minmax(0,1fr)}
 body .json-reference-thumb{width:32px;height:40px}
}
